// Mastery follows FTB Quests team progress; never grants or completes quests.
// The catalog is generated by tools/build-quests.ps1 alongside the quest book.
// KubeJS 8 JsonIO.read() only returns maps; a top-level JSON array becomes null.
const GSPACK_MASTERY_CATALOG = JSON.parse(JsonIO.readString('kubejs/data/gspack/mastery_chapters.json'))
if (!Array.isArray(GSPACK_MASTERY_CATALOG)) throw new Error('GSPack mastery catalog must be a JSON array')
const GSPACK_MASTERY_FILE = Java.loadClass('dev.ftb.mods.ftbquests.quest.ServerQuestFile')
const GSPACK_MASTERY_COMPONENT = Java.loadClass('net.minecraft.network.chat.Component')
const GSPACK_MASTERY_COLORS = { GOLD: 0xFFAA00, GREEN: 0x55FF55, GRAY: 0xAAAAAA, DARK_GRAY: 0x555555, AQUA: 0x55FFFF }
const GSPACK_MASTERY_COMMANDS = Java.loadClass('net.minecraft.commands.Commands')
const GSPACK_MASTERY_ENTITY = Java.loadClass('net.minecraft.commands.arguments.EntityArgument')
const GSPACK_MASTERY_STRING = Java.loadClass('com.mojang.brigadier.arguments.StringArgumentType')

function gspackMasteryChapters(file) {
  let chapters = {}
  file.forAllChapters(chapter => { chapters[String(chapter.getCodeString()).toUpperCase()] = chapter })
  return chapters
}

function gspackMasteryState(chapters, data, entry) {
  let chapter = chapters[String(entry.id).toUpperCase()]
  if (chapter == null) return null
  let total = 0
  let completed = 0
  for (let quest of chapter.getQuests()) {
    if (quest.isOptionalForProgression(data)) continue
    total++
    if (data.isCompleted(quest)) completed++
  }
  // Count current required quests, so adding a new quest cannot leave a stale
  // cached chapter-completion flag granting mastery too early.
  return { total: total, completed: completed, mastered: total > 0 && completed === total }
}

function gspackMasteryText(text, color) {
  return GSPACK_MASTERY_COMPONENT.literal(text).withColor(GSPACK_MASTERY_COLORS[color || 'GRAY'])
}

function gspackMasteryMessage(source, text, color) {
  // KubeJS remaps sendSuccess to the Component overload; Supplier callbacks
  // belong to sendSuccessLazy, otherwise Rhino prints the function itself.
  source.sendSuccess(gspackMasteryText(text, color), false)
}

function gspackShowMastery(source, player) {
  let file = GSPACK_MASTERY_FILE.getInstance()
  let chapters = gspackMasteryChapters(file)
  let team = file.getTeamData(player)
  if (!team.isPresent()) { gspackMasteryMessage(source, 'No FTB Quests progress found for this player.'); return 0 }
  let mastered = []
  for (let entry of GSPACK_MASTERY_CATALOG) {
    let state = gspackMasteryState(chapters, team.get(), entry)
    if (state != null && state.mastered) mastered.push(entry)
  }
  gspackMasteryMessage(source, `Mastery | ${player.getName().getString()}`, 'GOLD')
  gspackMasteryMessage(source, `${mastered.length} mastered chapters | shared team progress`, 'DARK_GRAY')
  if (!mastered.length) gspackMasteryMessage(source, 'No chapter mastery unlocked yet.', 'GRAY')
  for (let entry of mastered) {
    gspackMasteryMessage(source, `  + ${entry.title}`, 'GREEN')
  }
  return 1
}

function gspackShowChapterMasters(source, key) {
  let entry = null
  for (let candidate of GSPACK_MASTERY_CATALOG) { if (String(candidate.key) === key) { entry = candidate; break } }
  if (entry == null) { source.sendFailure(GSPACK_MASTERY_COMPONENT.literal(`Unknown chapter: ${key}. Use /mastery list.`)); return 0 }
  let file = GSPACK_MASTERY_FILE.getInstance()
  let chapters = gspackMasteryChapters(file)
  let names = []
  for (let player of source.getServer().getPlayerList().getPlayers()) {
    let data = file.getTeamData(player)
    if (data.isPresent()) {
      let state = gspackMasteryState(chapters, data.get(), entry)
      if (state != null && state.mastered) names.push(player.getName().getString())
    }
  }
  gspackMasteryMessage(source, `Chapter mastery | ${entry.title}`, 'GOLD')
  gspackMasteryMessage(source, `Online players: ${names.length ? names.join(', ') : 'none'}`, names.length ? 'GREEN' : 'GRAY')
  let teams = []
  for (let data of file.getAllTeamData()) {
    let state = gspackMasteryState(chapters, data, entry)
    if (state != null && state.mastered) teams.push(String(data.getName()))
  }
  gspackMasteryMessage(source, `Completed teams (including offline): ${teams.length ? teams.join(', ') : 'none'}`, teams.length ? 'AQUA' : 'GRAY')
  return names.length
}

ServerEvents.commandRegistry(event => {
  const C = GSPACK_MASTERY_COMMANDS
  event.register(C.literal('mastery')
    .requires(source => true)
    .executes(ctx => gspackShowMastery(ctx.getSource(), ctx.getSource().getPlayerOrException()))
    .then(C.literal('player').then(C.argument('player', GSPACK_MASTERY_ENTITY.player())
      .executes(ctx => gspackShowMastery(ctx.getSource(), GSPACK_MASTERY_ENTITY.getPlayer(ctx, 'player')))))
    .then(C.literal('chapter').then(C.argument('chapter', GSPACK_MASTERY_STRING.word())
      .suggests((ctx, builder) => {
        for (let entry of GSPACK_MASTERY_CATALOG) {
          if (String(entry.key).startsWith(String(builder.getRemaining()))) builder.suggest(String(entry.key))
        }
        return builder.buildFuture()
      })
      .executes(ctx => gspackShowChapterMasters(ctx.getSource(), GSPACK_MASTERY_STRING.getString(ctx, 'chapter')))))
    .then(C.literal('list').executes(ctx => {
      let keys = []
      for (let entry of GSPACK_MASTERY_CATALOG) keys.push(String(entry.key))
      gspackMasteryMessage(ctx.getSource(), 'Chapter keys: ' + keys.join(', '))
      return 1
    })))
})

function gspackUpdateMastery(player) {
  let file = GSPACK_MASTERY_FILE.getInstance()
  let chapters = gspackMasteryChapters(file)
  let team = file.getTeamData(player)
  if (!team.isPresent()) return
  let gained = []
  for (let entry of GSPACK_MASTERY_CATALOG) {
    let state = gspackMasteryState(chapters, team.get(), entry)
    if (state == null) continue
    let stage = 'gspack_mastery_' + String(entry.key)
    if (state.mastered && !player.stages.has(stage)) { player.stages.add(stage); gained.push(String(entry.title)) }
    else if (!state.mastered && player.stages.has(stage)) player.stages.remove(stage)
  }
  if (gained.length) player.tell(gspackMasteryText('Mastery unlocked: ' + gained.join(', ') + '. Use /mastery to view your mastered chapters.', 'GOLD'))
}
PlayerEvents.loggedIn(event => gspackUpdateMastery(event.player))
ServerEvents.tick(event => {
  if (event.server.tickCount % 200 !== 0) return
  for (let player of event.server.getPlayerList().getPlayers()) gspackUpdateMastery(player)
})
